import {test,after} from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync,realpathSync} from 'node:fs';import os from 'node:os';import path from 'node:path';import {buildImageSpawn} from './image-spawn.mjs';
const root=realpathSync(mkdtempSync('/tmp/talk-prod-rehearsal-'));
const environment={TALK_COMPARE_LABEL:'vps-compare-test',TALK_COMPARE_INGRESS_IMAGE:'sha256:'+'a'.repeat(64),TALK_COMPARE_WORKER_IMAGE:'sha256:'+'b'.repeat(64)};
const fixture={INGRESS_PRIVATE_ROOT:path.join(root,'ingress'),TALK_MEDIA_STORE_PATH:path.join(root,'media'),DATABASE_URL:'postgresql://fixture:fixture@127.0.0.1:55439/talk_rehearsal',INGRESS_AMQP_URL:'amqp://fixture:fixture@127.0.0.1:56739/talk_test',INGRESS_RECOVERY_ENABLED:'true',PRODUCTION_SECRET:'must-not-leak'};
after(()=>rmSync(root,{recursive:true}));
 test('exact entries select role image and VPS caps, never inherited secrets',()=>{for(const[entry,image,cpu,mem]of [['dist/ingress.js',environment.TALK_COMPARE_INGRESS_IMAGE,'0.5','512m'],['dist/ingress-worker.js',environment.TALK_COMPARE_WORKER_IMAGE,'0.75','768m']]){const x=buildImageSpawn(process.execPath,[entry],{env:fixture},environment);assert(x.args.includes(image));assert.equal(x.args[x.args.indexOf('--cpus')+1],cpu);assert.equal(x.args[x.args.indexOf('--memory')+1],mem);assert(!('PRODUCTION_SECRET'in x.options.env));assert(x.args.includes('--read-only'));assert(!x.args.includes('--privileged'));}});
 test('reject external URLs, shared DB/vhost and invalid image/label',()=>{for(const mutate of [{DATABASE_URL:'postgresql://x:x@prod.invalid:55439/talk_rehearsal'},{DATABASE_URL:'postgresql://x:x@127.0.0.1:55439/postgres'},{INGRESS_AMQP_URL:'amqp://x:x@127.0.0.1:56739/shared'},{WAHA_API_BASE_URL:'https://prod.invalid'}])assert.throws(()=>buildImageSpawn(process.execPath,['dist/ingress-worker.js'],{env:{...fixture,...mutate}},environment));for(const mutate of [{TALK_COMPARE_WORKER_IMAGE:'latest'},{TALK_COMPARE_LABEL:'other'}])assert.throws(()=>buildImageSpawn(process.execPath,['dist/ingress-worker.js'],{env:fixture},{...environment,...mutate}));});
 test('non-runtime commands remain outside image hook',()=>assert.equal(buildImageSpawn('pnpm',['test'],{},environment),null));
